content:
:root {
  --bg-color: #f5f7fa;
  --text-color: #333;
  --card-bg: #ffffff;
  --status-color: #4a5568;
  --timer-color: #2d3748;
  --progress-bg: #edf2f7;
  --progress-fill: #3182ce;
  --btn-start-bg: #3182ce;
  --btn-start-hover: #2b6cb0;
  --btn-pause-bg: #dd6b20;
  --btn-pause-hover: #c05621;
  --btn-reset-bg: #e2e8f0;
  --btn-reset-hover: #cbd5e0;
  --btn-reset-color: #4a5568;
  --instruction-color: #718096;
  --shadow-subtle: 0 10px 30px rgba(0, 0, 0, 0.08);
  --shadow-btn: 0 4px 6px rgba(0, 0, 0, 0.05);
  --focus-ring: 0 0 0 3px rgba(49, 130, 206, 0.4);
}

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, Helvetica, Arial, sans-serif;
  background-color: var(--bg-color);
  color: var(--text-color);
  display: flex;
  justify-content: center;
  align-items: center;
  min-height: 100vh;
}

.app-container {
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  width: 100%;
  max-width: 480px;
  padding: 2rem;
  margin: 0 auto;
}

.timer-card {
  background: var(--card-bg);
  border-radius: 24px;
  box-shadow: var(--shadow-subtle);
  padding: 2.5rem 2rem;
  width: 100%;
  display: flex;
  flex-direction: column;
  align-items: center;
  text-align: center;
}

.status-text {
  font-size: 1.25rem;
  font-weight: 600;
  color: var(--status-color);
  margin-bottom: 1.5rem;
  letter-spacing: 0.05em;
}

.timer-display {
  font-size: 5rem;
  font-weight: 700;
  color: var(--timer-color);
  font-variant-numeric: tabular-nums;
  margin-bottom: 2rem;
  letter-spacing: -0.02em;
}

.progress-container {
  width: 100%;
  height: 8px;
  background-color: var(--progress-bg);
  border-radius: 4px;
  overflow: hidden;
  margin-bottom: 2.5rem;
}

.progress-bar {
  height: 100%;
  background-color: var(--progress-fill);
  border-radius: 4px;
  transition: width 0.5s linear;
}

.controls {
  display: flex;
  gap: 1rem;
  width: 100%;
  justify-content: center;
  margin-bottom: 1.5rem;
}

.btn {
  flex: 1;
  padding: 0.875rem 1.5rem;
  font-size: 1rem;
  font-weight: 600;
  border: none;
  border-radius: 12px;
  cursor: pointer;
  transition: transform 0.1s ease, background-color 0.2s ease, box-shadow 0.2s ease;
  box-shadow: var(--shadow-btn);
}

.btn:active {
  transform: scale(0.98);
}

.btn:focus-visible {
  outline: none;
  box-shadow: var(--focus-ring);
}

.btn-start {
  background-color: var(--btn-start-bg);
  color: white;
}

.btn-start:hover {
  background-color: var(--btn-start-hover);
}

.btn-pause {
  background-color: var(--btn-pause-bg);
  color: white;
}

.btn-pause:hover {
  background-color: var(--btn-pause-hover);
}

.btn-reset {
  background-color: var(--btn-reset-bg);
  color: var(--btn-reset-color);
}

.btn-reset:hover {
  background-color: var(--btn-reset-hover);
}

.instruction {
  font-size: 0.875rem;
  color: var(--instruction-color);
  margin-top: 1rem;
}

@media (max-width: 480px) {
  .app-container {
    padding: 1rem;
  }

  .timer-card {
    padding: 1.5rem 1rem;
  }

  .timer-display {
    font-size: 4rem;
  }
}

import { useState, useEffect } from 'react';
import './index.css';

const TOTAL_TIME = 25 * 60; // 1500秒

export default function App() {
  const [timeLeft, setTimeLeft] = useState<number>(TOTAL_TIME);
  const [isRunning, setIsRunning] = useState<boolean>(false);
  const [isPaused, setIsPaused] = useState<boolean>(false);
  const [completedSessions, setCompletedSessions] = useState<number>(0);

  const playAlarm = () => {
    try {
      const audioCtx = new (window.AudioContext || (window as any).webkitAudioContext)();
      const osc = audioCtx.createOscillator();
      const gain = audioCtx.createGain();
      osc.type = 'sine';
      osc.frequency.value = 587.33; // D5
      gain.gain.setValueAtTime(0.1, audioCtx.currentTime);
      osc.connect(gain);
      gain.connect(audioCtx.destination);
      osc.start();
      osc.stop(audioCtx.currentTime + 0.5);
    } catch (e) {
      // AudioContextがブロックされている場合等のフォールバック
    }
  };

  useEffect(() => {
    let timer: number | undefined;
    if (isRunning && timeLeft > 0) {
      timer = window.setInterval(() => {
        setTimeLeft((prev) => {
          if (prev <= 1) {
            setIsRunning(false);
            setCompletedSessions((c) => c + 1);
            playAlarm();
            return 0;
          }
          return prev - 1;
        });
      }, 1000);
    }
    return () => {
      if (timer) clearInterval(timer);
    };
  }, [isRunning, timeLeft]);

  const handleStart = () => {
    setIsRunning(true);
    setIsPaused(false);
  };

  const handlePause = () => {
    setIsRunning(false);
    setIsPaused(true);
  };

  const handleReset = () => {
    setIsRunning(false);
    setIsPaused(false);
    setTimeLeft(TOTAL_TIME);
  };

  const minutes = Math.floor(timeLeft / 60);
  const seconds = timeLeft % 60;
  const formattedTime = `${String(minutes).padStart(2, '0')}:${String(seconds).padStart(2, '0')}`;

  const progress = ((TOTAL_TIME - timeLeft) / TOTAL_TIME) * 100;

  let statusText = 'ポモドーロタイマー';
  if (isRunning) {
    statusText = '集中中...';
  } else if (isPaused) {
    statusText = '一時停止中';
  } else if (timeLeft === 0) {
    statusText = '時間切れです！お疲れ様でした';
  }

  return (
    <div className="app-container">
      <div className="timer-card">
        <div className="status-text">{statusText}</div>
        <div className="timer-display">{formattedTime}</div>
        <div className="progress-container">
          <div className="progress-bar" style={{ width: `${progress}%` }}></div>
        </div>
        <div className="controls">
          {!isRunning ? (
            <button className="btn btn-start" onClick={handleStart}>
              {isPaused ? '再開' : 'スタート'}
            </button>
          ) : (
            <button className="btn btn-pause" onClick={handlePause}>
              一時停止
            </button>
          )}
          <button className="btn btn-reset" onClick={handleReset}>
            リセット
          </button>
        </div>
        <div className="instruction">
          25分間の集中セッションを開始しましょう。 (完了セッション数: {completedSessions}回)
        </div>
      </div>
    </div>
  );
}
